/**
 * Webstudio: the Cloudflare Worker that runs the CMS.
 *
 * Requests go to the app that OpenNext builds (.open-next/worker.js). On top
 * of that, the Cron in wrangler.jsonc ("triggers") calls scheduled() on the
 * 1st to 5th of every month, which sends the monthly report mails by calling
 * GET /api/cron/monthly-report with a key derived from BETTER_AUTH_SECRET
 * (see lib/monthly-report.ts), so there is no extra secret to set up.
 */

// @ts-ignore: generated by "opennextjs-cloudflare build"
import { default as handler } from "./.open-next/worker.js";

type Env = Record<string, unknown> & { BASE_URL?: string; BETTER_AUTH_SECRET?: string; AUTH_SECRET?: string };
type Context = { waitUntil: (promise: Promise<unknown>) => void; passThroughOnException?: () => void };

const cronKey = async (env: Env) => {
  const secret = String(env.BETTER_AUTH_SECRET || env.AUTH_SECRET || "");
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const signature = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode("webstudio-cron-v1"));
  return Array.from(new Uint8Array(signature)).map((byte) => byte.toString(16).padStart(2, "0")).join("");
};

const worker = {
  fetch: handler.fetch,

  async scheduled(controller: { cron: string; scheduledTime: number }, env: Env, ctx: Context) {
    const base = String(env.BASE_URL || "https://localhost").replace(/\/$/, "");
    const request = new Request(`${base}/api/cron/monthly-report`, {
      headers: { "x-cron-key": await cronKey(env), "user-agent": "Webstudio Cron" },
    });
    const response: Response = await handler.fetch(request, env, ctx);
    console.log(`Cron ${controller.cron}: monthly report ${response.status}`, await response.text());
  },
};

export default worker;
